"""ONE locked501-phase authoring evaluation; NO images, rendercalls, atlas or runtime writes."""
import sys
sys.dont_write_bytecode=True
import csv,fcntl,hashlib,json,pathlib,time
import numpy as np
import binding005 as b
BASE=pathlib.Path(__file__).resolve().parent
# Fixed samples: barycentric degree4 grid (vertices, edges, interiors) +centroid pertriangle.
BARY=np.asarray([(i/4,j/4,1-(i+j)/4) for i in range(5) for j in range(5-i)]+[(1/3,1/3,1/3)])
THRESHOLDS={'phaseCount':501,'clearanceMin':b.CLEARANCE,'clearanceTolerance':1e-8,'groundMin':-1e-9,'seamMax':1e-9,'neighborVertexStepMax':.030,'triangleAreaRatioMin':.05,'normalLengthResidualMax':1e-6,'sourceCanvasMax':256}

def main():
 if (BASE/'EVALUATION.json').exists() or (BASE/'evaluation-started.json').exists():raise ValueError('one evaluation only; existing receipt/start marker')
 custody=b.verify_inputs();start=time.time();(BASE/'evaluation-started.json').write_text(json.dumps({'evaluationBuildCount':1,'startedUnix':start,'thresholds':THRESHOLDS})+'\n');rows=[];globalmin=np.inf;worst={};minimum_ground=np.inf;maximum_delta=0;maximum_neighbor=0;minimum_area_ratio=np.inf;normal_residual=0;topology_ok=True;materials_ok=True;non_garment_ok=True;bounds_ok=True;finite_ok=True;length_ok=True;initial=None;previous=None;template_tri=None;template_colors=None;template_ids=None
 for i,t in enumerate(np.linspace(0,1,501)):
  p=b.pose(float(t));mesh,original,indices,gfaces=b.bind_pose(p);verts=np.asarray(mesh.v);tri=np.asarray(mesh.tri);colors=np.asarray(mesh.color);ids=np.asarray(mesh.ids);normals=np.asarray(mesh.n);other=np.ones(len(verts),bool);other[indices]=False
  finite_ok&=bool(np.all(np.isfinite(verts)) and np.all(np.isfinite(normals)));non_garment_ok&=bool(np.array_equal(verts[other],original[other]));length_ok&=bool(np.array_equal(verts[:,2],original[:,2]))
  if initial is None:initial=verts.copy();template_tri=tri.copy();template_colors=colors.copy();template_ids=ids.copy()
  topology_ok&=bool(np.array_equal(tri,template_tri));materials_ok&=bool(np.array_equal(colors,template_colors) and np.array_equal(ids,template_ids));delta=np.linalg.norm(verts[indices]-original[indices],axis=1);maximum_delta=max(maximum_delta,float(delta.max()));neighbor=0 if previous is None else float(np.linalg.norm(verts[indices]-previous[indices],axis=1).max());maximum_neighbor=max(maximum_neighbor,neighbor);previous=verts.copy()
  minimum_ground=min(minimum_ground,float(verts[:,2].min()));world=verts@b.MOTION.BASIS.T;proj=b.MOTION.project_vertices(world);lo=proj[:,:2].min(axis=0);hi=proj[:,:2].max(axis=0);bounds_ok&=bool(np.all(lo>=0) and np.all(hi<256))
  gt=tri[gfaces];points=np.einsum('sk,tkd->tsd',BARY,verts[gt]).reshape(-1,3);clear=b.signed_clearance(points,p);small=int(np.argmin(clear));phase_min=float(clear[small]);globalmin=min(globalmin,phase_min)
  if not worst or phase_min<worst['clearance']:worst={'phase':float(t),'garmentFaceOrdinal':small//len(BARY),'sampleIndex':small%len(BARY),'sampleLocalXYZ':points[small].tolist(),'clearance':phase_min}
  oldareas=np.linalg.norm(np.cross(original[gt[:,1]]-original[gt[:,0]],original[gt[:,2]]-original[gt[:,0]]),axis=1);newareas=np.linalg.norm(np.cross(verts[gt[:,1]]-verts[gt[:,0]],verts[gt[:,2]]-verts[gt[:,0]]),axis=1);valid=oldareas>1e-12;ratio=float((newareas[valid]/oldareas[valid]).min());minimum_area_ratio=min(minimum_area_ratio,ratio);nlen=np.linalg.norm(normals[indices],axis=1);normal_residual=max(normal_residual,float(np.abs(nlen-1).max()))
  rows.append({'phase':float(t),'minimumTriangleSampleClearance':phase_min,'samplesBelowClearance':int(np.sum(clear<b.CLEARANCE-1e-8)),'maximumGarmentVertexDisplacement':float(delta.max()),'neighborStepMax':neighbor,'groundMin':float(verts[:,2].min()),'garmentAreaRatioMin':ratio,'bounds':lo.tolist()+hi.tolist()})
  if i%100==0:print(json.dumps({'phaseIndex':i,'sampledClearanceMin':phase_min}),flush=True)
 seam=float(np.abs(previous-initial).max());technical={'finite':finite_ok,'nonGarmentGeometryExact':non_garment_ok,'topologyExactAcrossPhases':topology_ok,'materialsAndIDsExactAcrossPhases':materials_ok,'garmentLengthVertexZExact':length_ok,'sourceCanvasBounds':bounds_ok,'ground':minimum_ground>=-1e-9,'phaseSeam':seam<=1e-9,'neighborStep':maximum_neighbor<=.03,'sampledTriangleClearance':globalmin>=b.CLEARANCE-1e-8,'triangleAreaRatio':minimum_area_ratio>=.05,'garmentNormalsUnit':normal_residual<=1e-6};passed=all(technical.values());custody_after=b.verify_inputs();assert custody==custody_after
 with (BASE/'evaluation-phases.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 result={'schema':'whole-garment-binding-evaluation/v1','status':'AUTHORING_NUMERIC_PASS_PARENT_REVIEW_PENDING' if passed else 'HELD_STOP_BINDING_EVALUATION_FAILED','technicalPass':passed,'gates':technical,'thresholds':THRESHOLDS,'evaluationBuildCount':1,'phaseCount':501,'garmentTriangleCount':int(np.sum(template_ids==1)),'samplesPerTrianglePerPhase':len(BARY),'samplingMethod':'degree4 barycentricgrid plus centroid on everytunic triangle; includes lower shell/lapels/overlap panels/hem. This is sampledclearance only, not exact triangle-capsule intersection or CCD.','capsuleEnvelopeRadii':b.CAPSULE_RADII,'clearanceRequired':b.CLEARANCE,'vertexChordMargin':b.CHORD_MARGIN,'radialMovementCap':b.MAX_RADIAL_STEP,'fullBindingRestZMax':b.LOWER_FULL_REST_Z,'anchorRestZ':b.UPPER_ANCHOR_REST_Z,'minimumSampleClearance':globalmin,'worstSample':worst,'maxGarmentDisplacementModelUnits':maximum_delta,'maxGarmentDisplacementGameplay80Px':maximum_delta*b.MOTION.GAME_PX_PER_MODEL,'maxNeighborVertexStepModelUnits':maximum_neighbor,'phaseSeamResidual':seam,'groundMin':minimum_ground,'triangleAreaRatioMin':minimum_area_ratio,'normalLengthResidualMax':normal_residual,'inputCustody':custody,'inputsUnchanged':True,'sourceFrames':0,'renderCalls':0,'aiCalls':0,'runtimeChanges':False,'appearanceAccepted':False,'motionAccepted':False,'ownerAccepted':False,'fanoutOpened':False,'limitations':['Uniform worst-radius legcapsules overestimatehip/ankle volumes and may force excessive skirt bulge; this cannot establish canonical silhouette.','Anchored uppertransition may failclearance whereconservativehipcaps overlap waist.','Vertex-only outwardwarp withfixedtopology can leave triangle interiors penetrating despite vertexmargin; allsample failures remainheld.','No fabric dynamics/cloth selfcollision/inter-panel collision/triangleexactcollision/continuouscollision proof.','Finite501phase sampling canmiss betweenphase extrema; degree4 triangle samples canmiss unsampledinteriors.','No PNG or appearance trial; models001–004 remainmotion scaffolds, not realisticfinalart.'],'elapsedSec':time.time()-start,'sourceHashes':{n:b.sha(BASE/n) for n in ['binding005.py','evaluate-binding.py','WORK_ORDER.json']}}
 (BASE/'EVALUATION.json').write_text(json.dumps(result,indent=2)+'\n');ready={'status':result['status'],'technicalPass':passed,'parentReviewRequired':True,'appearanceAccepted':False,'motionAccepted':False,'fanoutOpened':False,'evaluationBuildCount':1,'inputsUnchanged':True,'artifacts':{name:b.sha(BASE/name) for name in ['binding005.py','evaluate-binding.py','WORK_ORDER.json','EVALUATION.json','evaluation-phases.csv']}}
 (BASE/'READY.json').write_text(json.dumps(ready,indent=2)+'\n');(BASE/'READY.md').write_text('# Whole-garment binding005\n\n'+result['status']+'\n\nOne501-phase analytic evaluation; no image/render/sourceframes. Technical pass: '+str(passed)+'. Minimum sampled clearance '+str(globalmin)+'; required '+str(b.CLEARANCE)+'. Max garment movement '+str(maximum_delta)+' modelunits ('+str(result['maxGarmentDisplacementGameplay80Px'])+' gameplay80px).\n\n'+('All declared numeric gates pass; parent independently reviews this authoring prerequisite.' if passed else 'Held: '+', '.join(k for k,v in technical.items() if not v)+'. Stop; no revision/retry performed.')+'\n\nCapsules intentionally conservative. Sampled clearance is not exactcollision, realisticappearance, motion, owner or production approval. Originaltopology/materials/non-garment vertices preserved; same field binds lower shell and all overlappingpanel/hem vertices, garmentZ/length retained; changedgarment normals recomputed. Frozen inputs unchanged.\n\nReproduction requires a fresh authorized lease, pinnedWORK_ORDER +bothscripts and same frozenrepo paths: `python3 evaluate-binding.py`. The script acquires `/tmp/tn-heavy-gate.lock` and refuses a second evaluation in the samelease.\n')
 print(json.dumps({'status':result['status'],'minimumSampleClearance':globalmin,'technicalGates':technical}),flush=True)

if __name__=='__main__':
 with open('/tmp/tn-heavy-gate.lock','a+') as lock:fcntl.flock(lock,fcntl.LOCK_EX);main()
